INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l16','accuse sb of doing','',NULL,'/əˈkjuːz əv/','Dan accused Earl of stealing the lamb.','丹指控厄尔偷了羊。','Don''t accuse me of lying.','别指责我撒谎。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l16','had better','',NULL,'/hæd ˈbetər/','You had better return it right now.','你最好现在就还回去。','We''d better hurry, or we''ll be late.','我们最好快点,不然要迟到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l16','apologize for doing','',NULL,'/əˈpɑːlədʒaɪz fɔːr/','He apologized for accusing his neighbor.','他为错怪邻居而道歉。','I apologize for being late.','我为迟到道歉。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l16','jump to conclusions','',NULL,'/dʒʌmp tə kənˈkluːʒnz/','Dan jumped to conclusions too fast.','丹太快就妄下结论了。','Don''t jump to conclusions before you know the facts.','没弄清事实前别急着下结论。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp1','choice','{"stem":"\"Dan accused Earl ___ stealing the lamb.\"(accuse sb 后接哪个介词)","options":["about","for","with","of"],"answer_index":3,"stem_cn":"丹指控厄尔偷了羊。","explanation_cn":"accuse sb of doing sth“指控某人做了某事”,介词固定用 of。✓ accused Earl of stealing. ✗ for / with / about:accuse 搭配的介词是 of。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp1','choice','{"stem":"\"The police suspected him ___ taking the money.\"(suspect sb 后接哪个介词)","options":["of","for","to","with"],"answer_index":0,"stem_cn":"警方怀疑他拿了钱。","explanation_cn":"suspect sb of doing sth“怀疑某人做了某事”,介词也用 of。✓ suspected him of taking the money. ✗ for / to / with:suspect 搭配的介词是 of。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp1','choice','{"stem":"\"He accused me of ___ his tools without asking.\"(accuse sb of 后接动词哪种形式)","options":["to borrow","borrowed","borrowing","borrow"],"answer_index":2,"stem_cn":"他指责我没打招呼就拿了他的工具。","explanation_cn":"介词 of 后面接动词要用 -ing 形式:of borrowing。✓ accused me of borrowing his tools. ✗ borrow / to borrow / borrowed:介词后要用 -ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp2','choice','{"stem":"\"Earl denied ___ the lamb.\"(deny 后接动词哪种形式)","options":["taken","take","to take","taking"],"answer_index":3,"stem_cn":"厄尔否认拿过那只羊。","explanation_cn":"deny 后面直接接 -ing 形式:deny taking。✓ Earl denied taking the lamb. ✗ to take / take / taken:deny 后接 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp2','choice','{"stem":"\"The boy admitted ___ the window.\"(admit 后接动词哪种形式)","options":["to break","break","breaking","broke"],"answer_index":2,"stem_cn":"男孩承认打碎了窗户。","explanation_cn":"admit 后面直接接 -ing 形式:admit breaking。✓ admitted breaking the window. ✗ to break / break / broke:admit 后接 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp2','choice','{"stem":"\"Mary enjoys ___ care of her little lamb.\"(enjoy 后接动词哪种形式)","options":["take","took","to take","taking"],"answer_index":3,"stem_cn":"玛丽喜欢照看她的小羊。","explanation_cn":"enjoy 后面直接接 -ing 形式:enjoy taking。✓ enjoys taking care of her lamb. ✗ to take / take / took:enjoy 后接 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp3','choice','{"stem":"\"Dan was ashamed ___ having accused an innocent man.\"(be ashamed 后接哪个介词)","options":["of","for","with","to"],"answer_index":0,"stem_cn":"丹为错怪了好人而羞愧。","explanation_cn":"be ashamed of doing“为做…而羞愧”,介词用 of。✓ ashamed of having accused him. ✗ for / to / with:ashamed 搭配的介词是 of。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp3','choice','{"stem":"\"He apologized ___ jumping to conclusions.\"(apologize 后接哪个介词)","options":["to","in","of","for"],"answer_index":3,"stem_cn":"他为妄下结论而道歉。","explanation_cn":"apologize for doing“为做…而道歉”,介词用 for。✓ apologized for jumping to conclusions. ✗ of / to / in:apologize 后接 for + doing(to 用在人前面:apologize to sb)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp3','choice','{"stem":"\"She apologized for ___ so rude to her neighbor.\"(apologize for 后接动词哪种形式)","options":["been","to be","being","be"],"answer_index":2,"stem_cn":"她为对邻居那么无礼而道歉。","explanation_cn":"介词 for 后面接动词要用 -ing 形式:for being。✓ apologized for being so rude. ✗ to be / be / been:介词后要用 -ing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp4','choice','{"stem":"\"You ___ return the lamb, or I''ll call the sheriff.\"(表示“最好…”的忠告)","options":["had to better","had better","would better","better had"],"answer_index":1,"stem_cn":"你最好把羊还回来,不然我就报警。","explanation_cn":"“最好…”的忠告用 had better + 动词原形。✓ You had better return the lamb. ✗ would better / had to better / better had:固定说 had better。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp4','choice','{"stem":"\"It''s getting late — we ___ leave now.\"(表示“最好…”的忠告)","options":["had better","would rather better","had best to","better to"],"answer_index":0,"stem_cn":"天晚了,我们最好现在走。","explanation_cn":"“最好…”的忠告用 had better。✓ we had better leave now. ✗ would rather better / had best to / better to:固定说 had better。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp4','choice','{"stem":"\"You had better ___ the sheriff about the theft.\"(had better 后接动词哪种形式)","options":["telling","tell","to tell","told"],"answer_index":1,"stem_cn":"你最好把偷窃的事告诉警长。","explanation_cn":"had better 后面接动词原形:had better tell。✓ You had better tell the sheriff. ✗ to tell / telling / told:had better 后用原形。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp5','choice','{"stem":"\"You ___ accuse people without any proof.\"(表示“最好别…”)","options":["had better not","had not better","would not better","better not had"],"answer_index":0,"stem_cn":"没有证据,你最好别指控别人。","explanation_cn":"“最好别…”用 had better not + 原形,not 放在 better 后面。✓ You had better not accuse people. ✗ had not better / better not had / would not better:语序错误。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp5','choice','{"stem":"\"We had better not ___ out in this storm.\"(had better not 后接动词哪种形式)","options":["to go","go","went","going"],"answer_index":1,"stem_cn":"这么大的暴风雨,我们最好别出门。","explanation_cn":"had better not 后面同样接动词原形:had better not go。✓ We had better not go out. ✗ to go / going / went:后用原形。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp5','choice','{"stem":"\"You''d better ___ him now; he''s still angry.\"(表示“最好别…”)","options":["no call","not to call","don''t call","not call"],"answer_index":3,"stem_cn":"你最好现在别给他打电话,他还在气头上。","explanation_cn":"“最好别做某事”用 had better not + 原形:''d better not call。✓ You''d better not call him now. ✗ not to call / don''t call / no call:had better 的否定是 not + 原形。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp6','choice','{"stem":"\"Something that is easy to see or understand is ___.\"(“显而易见的”用哪个词)","options":["difficult","obvious","secret","invisible"],"answer_index":1,"stem_cn":"一眼就能看明白的就是显而易见的。","explanation_cn":"一眼就能看明白的是 obvious(显而易见的)。✓ it was obvious that… ✗ secret 秘密的;✗ invisible 看不见的;✗ difficult 困难的——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp6','choice','{"stem":"\"To color cloth or wool a new color is to ___ it.\"(“染色”用哪个词)","options":["dye","fold","wash","tear"],"answer_index":0,"stem_cn":"把布或羊毛染上新颜色就是这个词。","explanation_cn":"把布或羊毛染上新颜色用 dye(染)。✓ wool that had been dyed black. ✗ wash 洗;✗ fold 叠;✗ tear 撕——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',5,'am3_l16_gp6','choice','{"stem":"\"The act of stealing something is called ___.\"(“偷窃行为”用哪个词)","options":["health","gift","feast","theft"],"answer_index":3,"stem_cn":"偷东西的行为叫作 theft。","explanation_cn":"偷东西的行为叫 theft(偷窃)。✓ the theft of the lamb. ✗ gift 礼物;✗ feast 盛宴;✗ health 健康——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"prize 的意思是:","options":["破旧的","珍贵的,宝贵的","普通的","廉价的"],"answer_index":1,"explanation_cn":"prize = 珍贵的、宝贵的(prize possession 最珍爱之物)。✓ her prize possession.\n顺带记:廉价的 = cheap;普通的 = ordinary;破旧的 = shabby."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"theft 的意思是:","options":["礼物","宴会","旅行","偷盗行为"],"answer_index":3,"explanation_cn":"theft = 偷盗行为、偷窃案。✓ the theft of the lamb 羊被偷的案子。\n顺带记:礼物 = gift;宴会 = feast;旅行 = trip."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"accuse 的意思是:","options":["指控,指责","邀请","表扬","原谅"],"answer_index":0,"explanation_cn":"accuse = 指控、指责(accuse sb of doing)。✓ accused Earl of stealing 指控厄尔偷窃。\n顺带记:表扬 = praise;原谅 = forgive;邀请 = invite."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"deny 的意思是:","options":["相信","承认","证明","否认"],"answer_index":3,"explanation_cn":"deny = 否认(deny doing)。✓ denied taking anything 否认拿过任何东西。\n顺带记:承认 = admit;证明 = prove;相信 = believe."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"ashamed 的意思是:","options":["放松的","感到羞耻的","骄傲的","高兴的"],"answer_index":1,"explanation_cn":"ashamed = 感到羞耻的、惭愧的。✓ ashamed of having accused him 为错怪他而羞愧。\n顺带记:骄傲的 = proud;高兴的 = glad;放松的 = relaxed."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',6,NULL,'choice','{"stem":"dye 的意思是:","options":["晒","洗","染(色)","剪"],"answer_index":2,"explanation_cn":"dye = 染(色)。✓ wool that had been dyed black 被染黑的羊毛。\n顺带记:洗 = wash;剪 = cut;晒 = dry."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',7,NULL,'cloze','{"stem":"第 1 空","context":"When Mary''s white lamb went missing, Dan accused his neighbor Earl ___1___ stealing it and said he ___2___ return it at once. But Earl denied ___3___ anything and showed Dan a black lamb. Ashamed of having accused an innocent man, Dan apologized ___4___ jumping to conclusions. Then the rain washed the black dye away, and the lamb turned white!","blank_no":1,"options":["of","for","with","to"],"answer_index":0,"explanation_cn":"accuse sb of doing,介词用 of。✓ accused his neighbor Earl of stealing it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',7,NULL,'cloze','{"stem":"第 2 空","context":"When Mary''s white lamb went missing, Dan accused his neighbor Earl ___1___ stealing it and said he ___2___ return it at once. But Earl denied ___3___ anything and showed Dan a black lamb. Ashamed of having accused an innocent man, Dan apologized ___4___ jumping to conclusions. Then the rain washed the black dye away, and the lamb turned white!","blank_no":2,"options":["had better","would better","better had","had to"],"answer_index":0,"explanation_cn":"“最好…”的忠告用 had better + 原形。✓ he had better return it at once."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',7,NULL,'cloze','{"stem":"第 3 空","context":"When Mary''s white lamb went missing, Dan accused his neighbor Earl ___1___ stealing it and said he ___2___ return it at once. But Earl denied ___3___ anything and showed Dan a black lamb. Ashamed of having accused an innocent man, Dan apologized ___4___ jumping to conclusions. Then the rain washed the black dye away, and the lamb turned white!","blank_no":3,"options":["taking","to take","take","taken"],"answer_index":0,"explanation_cn":"deny 后接 -ing 形式。✓ Earl denied taking anything."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',7,NULL,'cloze','{"stem":"第 4 空","context":"When Mary''s white lamb went missing, Dan accused his neighbor Earl ___1___ stealing it and said he ___2___ return it at once. But Earl denied ___3___ anything and showed Dan a black lamb. Ashamed of having accused an innocent man, Dan apologized ___4___ jumping to conclusions. Then the rain washed the black dye away, and the lamb turned white!","blank_no":4,"options":["for","of","to","about"],"answer_index":0,"explanation_cn":"apologize for doing,介词用 for。✓ Dan apologized for jumping to conclusions."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',8,NULL,'choice','{"stem":"How did Dan know the lamb had been stolen?","options":["The rope had been cut","The gate was left open","He saw the thief run away","The lamb was calling out"],"answer_index":0,"explanation_cn":"课文说 The rope had been cut, so it was obvious that the lamb had been stolen——绳被割断,所以断定羊被偷了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',8,NULL,'choice','{"stem":"Why did Dan apologize to Earl?","options":["Earl looked very angry","Earl offered him money","Earl''s lamb was black, not white","Earl was his oldest friend"],"answer_index":2,"explanation_cn":"课文说 his lamb was black,丹这才发现指控错了,于是道歉。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',8,NULL,'choice','{"stem":"What made the black lamb turn white?","options":["It was a different lamb","The sun bleached its wool","Someone painted it white","The rain washed off the dye"],"answer_index":3,"explanation_cn":"课文说 Its wool, which had been dyed black, had been washed clean by the rain——雨把染黑的羊毛冲干净了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',9,NULL,'choice','{"stem":"你想说\"丹指控厄尔偷了羊\"(accuse sb of doing):","options":["Dan accused Earl of stealing the lamb.","Dan accused Earl for stealing the lamb.","Dan accused Earl of steal the lamb.","Dan accused Earl to steal the lamb."],"answer_index":0,"explanation_cn":"accuse sb of doing:介词 of + 动词 -ing。✓ Dan accused Earl of stealing the lamb. 场合:指控某人做了某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',9,NULL,'choice','{"stem":"你想说\"你最好把羊还回来\"(had better + 原形):","options":["You would better return the lamb.","You had better return the lamb.","You had best returning the lamb.","You had better to return the lamb."],"answer_index":1,"explanation_cn":"“最好…”用 had better + 动词原形。✓ You had better return the lamb. 场合:强烈地劝告某人做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',9,NULL,'choice','{"stem":"你想说\"他为错怪邻居而道歉\"(apologize for doing):","options":["He apologized to accusing his neighbor.","He apologized of accusing his neighbor.","He apologized for accuse his neighbor.","He apologized for accusing his neighbor."],"answer_index":3,"explanation_cn":"apologize for doing:介词 for + 动词 -ing。✓ He apologized for accusing his neighbor. 场合:为自己做过的事道歉。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"accuse 的意思是:","options":["表扬","邀请","指控,指责","原谅"],"answer_index":2,"explanation_cn":"accuse = 指控、指责。✓ accused Earl of stealing."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"dye 的意思是:","options":["染(色)","剪","洗","晒"],"answer_index":0,"explanation_cn":"dye = 染(色)。✓ wool dyed black."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"\"Dan accused Earl ___ stealing the lamb.\"(accuse sb 后接哪个介词)","options":["to","with","for","of"],"answer_index":3,"stem_cn":"丹指控厄尔偷了羊。","explanation_cn":"accuse sb of doing,介词用 of。✓ Dan accused Earl of stealing the lamb. ✗ for / with / to:accuse 搭配 of。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"\"You ___ return it, or I''ll call the sheriff.\"(表示“最好…”的忠告)","options":["had better","would better","had to","better had"],"answer_index":0,"stem_cn":"你最好还回去,不然我就报警。","explanation_cn":"“最好…”的忠告用 had better + 原形。✓ You had better return it. ✗ would better / better had / had to:固定说 had better。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"\"accuse sb of doing\" 的意思是:","options":["请求某人做某事","允许某人做某事","指控某人做了某事","感谢某人做某事"],"answer_index":2,"explanation_cn":"accuse sb of doing = 指控某人做了某事。✓ accuse Earl of stealing 指控厄尔偷窃。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"\"jump to conclusions\" 的意思是:","options":["得出正确答案","匆忙下结论","跳过难题","提出问题"],"answer_index":1,"explanation_cn":"jump to conclusions = 匆忙下结论、妄下判断。✓ Don''t jump to conclusions 别急着下结论。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"Why was Dan sure he could find the thief?","options":["The police helped him","He had seen the thief","The lamb left clear tracks","The town was very small"],"answer_index":3,"passage":"Mary and her husband Dan lived on a small farm just outside a quiet town. One of Mary''s prize possessions was a little white lamb that Dan had given her. She kept it tied to a post in the meadow during the day and went to bring it in every evening. One evening, however, the lamb was gone. The rope had been cut, so it was obvious that the lamb had been stolen. When Dan came in from the fields, Mary told him what had happened. Dan set out at once to find out who had taken it, sure that in such a small town it would not be hard. After asking around, he learned that his neighbor, Earl, had suddenly gotten himself a new lamb. Dan marched over and accused Earl of stealing it, warning him that he had better return it or he would call the sheriff. Earl denied taking anything and led Dan into his backyard. It was true that he had just bought a lamb, he said, but his lamb was black. Ashamed of having accused an innocent man, Dan apologized for jumping to conclusions. While they were talking, it began to rain, and Dan waited under the porch until it stopped. When he stepped outside half an hour later, he was astonished: the little black lamb had turned almost white. Its wool, which had been dyed black, had been washed clean by the rain!","explanation_cn":"课文说 sure that in such a small town it would not be hard——镇子小,丹相信不难找出是谁拿的。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"What was strange about the lamb after the rain?","options":["It had grown much bigger","It had turned almost white","It had changed owners","It had run away again"],"answer_index":1,"passage":"Mary and her husband Dan lived on a small farm just outside a quiet town. One of Mary''s prize possessions was a little white lamb that Dan had given her. She kept it tied to a post in the meadow during the day and went to bring it in every evening. One evening, however, the lamb was gone. The rope had been cut, so it was obvious that the lamb had been stolen. When Dan came in from the fields, Mary told him what had happened. Dan set out at once to find out who had taken it, sure that in such a small town it would not be hard. After asking around, he learned that his neighbor, Earl, had suddenly gotten himself a new lamb. Dan marched over and accused Earl of stealing it, warning him that he had better return it or he would call the sheriff. Earl denied taking anything and led Dan into his backyard. It was true that he had just bought a lamb, he said, but his lamb was black. Ashamed of having accused an innocent man, Dan apologized for jumping to conclusions. While they were talking, it began to rain, and Dan waited under the porch until it stopped. When he stepped outside half an hour later, he was astonished: the little black lamb had turned almost white. Its wool, which had been dyed black, had been washed clean by the rain!","explanation_cn":"课文说 the little black lamb had turned almost white——雨后黑羊几乎变白了,这最奇怪。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"What had Earl done to the stolen lamb?","options":["He had sold it to a farmer","He had hidden it in a barn","He had shaved off its wool","He had dyed its wool black"],"answer_index":3,"audio":"Mary and her husband Dan lived on a small farm just outside a quiet town. One of Mary''s prize possessions was a little white lamb that Dan had given her. She kept it tied to a post in the meadow during the day and went to bring it in every evening. One evening, however, the lamb was gone. The rope had been cut, so it was obvious that the lamb had been stolen. When Dan came in from the fields, Mary told him what had happened. Dan set out at once to find out who had taken it, sure that in such a small town it would not be hard. After asking around, he learned that his neighbor, Earl, had suddenly gotten himself a new lamb. Dan marched over and accused Earl of stealing it, warning him that he had better return it or he would call the sheriff. Earl denied taking anything and led Dan into his backyard. It was true that he had just bought a lamb, he said, but his lamb was black. Ashamed of having accused an innocent man, Dan apologized for jumping to conclusions. While they were talking, it began to rain, and Dan waited under the porch until it stopped. When he stepped outside half an hour later, he was astonished: the little black lamb had turned almost white. Its wool, which had been dyed black, had been washed clean by the rain!","explanation_cn":"课文说 Its wool…had been dyed black——厄尔把偷来的白羊羊毛染成了黑色。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l16',10,NULL,'choice','{"stem":"Where did Dan wait while it rained?","options":["At the store","Under Earl''s porch","In his own house","In the meadow"],"answer_index":1,"audio":"Mary and her husband Dan lived on a small farm just outside a quiet town. One of Mary''s prize possessions was a little white lamb that Dan had given her. She kept it tied to a post in the meadow during the day and went to bring it in every evening. One evening, however, the lamb was gone. The rope had been cut, so it was obvious that the lamb had been stolen. When Dan came in from the fields, Mary told him what had happened. Dan set out at once to find out who had taken it, sure that in such a small town it would not be hard. After asking around, he learned that his neighbor, Earl, had suddenly gotten himself a new lamb. Dan marched over and accused Earl of stealing it, warning him that he had better return it or he would call the sheriff. Earl denied taking anything and led Dan into his backyard. It was true that he had just bought a lamb, he said, but his lamb was black. Ashamed of having accused an innocent man, Dan apologized for jumping to conclusions. While they were talking, it began to rain, and Dan waited under the porch until it stopped. When he stepped outside half an hour later, he was astonished: the little black lamb had turned almost white. Its wool, which had been dyed black, had been washed clean by the rain!","explanation_cn":"课文说 Dan waited under the porch until it stopped——下雨时丹在厄尔家门廊下躲雨。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
